#include <LiquidCrystal.h>

// ========================================
// Smart Greenhouse - PID Temperature Control
// Arduino UNO + Proteus
// ========================================

// LCD pins: RS, E, D4, D5, D6, D7
LiquidCrystal lcd(12, 11, 5, 4, 3, 2);

// Output pins
const int FAN_PIN = 10;       // PWM
const int HEATER_PIN = 9;     // PWM

// ========================================
// Temperature settings
// ========================================

double setpoint = 25.0;       // Target temperature in Celsius
double temperature = 20.0;    // Initial simulated temperature
const double ambientTemperature = 20.0;

// ========================================
// PID parameters
// Initial values for simulation testing
// ========================================

double Kp = 12.0;
double Ki = 0.15;
double Kd = 3.0;

double integral = 0.0;
double previousError = 0.0;

// ========================================
// Thermal model parameters
// These values control simulated temperature changes
// ========================================

const double heatingRate = 0.12;
const double coolingRate = 0.18;
const double naturalLoss = 0.015;

// ========================================
// Timing
// ========================================

const unsigned long CONTROL_INTERVAL = 100;
const unsigned long DISPLAY_INTERVAL = 500;

unsigned long previousControlTime = 0;
unsigned long previousDisplayTime = 0;

// Current outputs
int heaterPWM = 0;
int fanPWM = 0;

// ========================================
// Setup
// ========================================

void setup() {
  pinMode(FAN_PIN, OUTPUT);
  pinMode(HEATER_PIN, OUTPUT);

  analogWrite(FAN_PIN, 0);
  analogWrite(HEATER_PIN, 0);

  lcd.begin(16, 2);
  lcd.clear();

  lcd.setCursor(0, 0);
  lcd.print("Smart Greenhouse");

  lcd.setCursor(0, 1);
  lcd.print("PID Starting...");

  delay(1500);

  lcd.clear();

  unsigned long now = millis();
  previousControlTime = now;
  previousDisplayTime = now;
}

// ========================================
// Main loop
// ========================================

void loop() {
  unsigned long now = millis();

  // --------------------------------------
  // PID control update
  // --------------------------------------

  if (now - previousControlTime >= CONTROL_INTERVAL) {

    double dt =
        (now - previousControlTime) / 1000.0;

    previousControlTime = now;

    // Calculate error
    double error = setpoint - temperature;

    // Integral term with basic anti-windup
    integral += error * dt;
    integral = constrain(integral, -50.0, 50.0);

    // Derivative term
    double derivative = 0.0;

    if (dt > 0.0) {
      derivative = (error - previousError) / dt;
    }

    previousError = error;

    // PID output
    double pidOutput =
        (Kp * error) +
        (Ki * integral) +
        (Kd * derivative);

    // Limit output to PWM range
    pidOutput = constrain(pidOutput, -255.0, 255.0);

    // ------------------------------------
    // Heating / cooling decision
    // ------------------------------------

    if (pidOutput > 0.0) {
      heaterPWM = (int)pidOutput;
      fanPWM = 0;
    }
    else if (pidOutput < 0.0) {
      heaterPWM = 0;
      fanPWM = (int)(-pidOutput);
    }
    else {
      heaterPWM = 0;
      fanPWM = 0;
    }

    // Apply PWM outputs
    analogWrite(HEATER_PIN, heaterPWM);
    analogWrite(FAN_PIN, fanPWM);

    // ------------------------------------
    // Simulated thermal response
    // ------------------------------------

    double heatingEffect =
        heatingRate * (heaterPWM / 255.0);

    double coolingEffect =
        coolingRate * (fanPWM / 255.0);

    double ambientEffect =
        naturalLoss * (ambientTemperature - temperature);

    temperature +=
        (heatingEffect - coolingEffect + ambientEffect) * dt;

    // Safety limits for the simulated temperature
    temperature = constrain(temperature, 0.0, 60.0);
  }

  // --------------------------------------
  // LCD update
  // --------------------------------------

  if (now - previousDisplayTime >= DISPLAY_INTERVAL) {

    previousDisplayTime = now;

    // First row: simulated temperature
    lcd.setCursor(0, 0);
    lcd.print("Temp:");
    lcd.print(temperature, 1);
    lcd.write(byte(223));
    lcd.print("C   ");

    // Second row: current operating mode
    lcd.setCursor(0, 1);

    if (heaterPWM > 0) {
      lcd.print("HEATING         ");
    }
    else if (fanPWM > 0) {
      lcd.print("COOLING         ");
    }
    else {
      lcd.print("OUTPUT OFF      ");
    }
  }
}
